/* Whole minutes in secs; the leftover seconds are discarded. */
int whole_minutes(int secs) {
    return secs / 60;
}

int main(void) {
    printf("%d %d\n", whole_minutes(59), whole_minutes(125));
    return 0;
}

#include <stdio.h>

int total(const int *a, int n) {
    int s = 0;
    for (int i = 0; i < n; i++)
        s += a[i];
    return s;
}

int main(void) {
    int a[3] = {1, 2, 3};
    printf("%d %d\n", total(a, 3), total(a, 0));
}

